fn treats_shell_syntax_as_user_data() {
    let unique = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let marker = std::env::temp_dir().join(format!(
        "report-user-{}-{unique}",
        std::process::id()
    ));
    let quoted_marker = marker.to_str().unwrap().replace('\'', "'\"'\"'");
    let user = format!("alice; printf injected > '{quoted_marker}'");
    let _ = render_report(&user, vec!["first".into(), "second".into()]);
    let created = marker.exists();
    if created {
        std::fs::remove_file(&marker).unwrap();
    }
    assert!(!created, "user input must not execute shell commands");
}

